            if status.is_server_error() {
                Some("http.server_error")
            } else if status.is_client_error() {
                Some("http.client_error")
            } else {
                None
            }
        });
    let route = route.map(MatchedPath::as_str);
    macro_rules! emit {
        ($level:expr) => {
            tracing::event!(
                $level,
                name = "http.request.completed",
                http.request.method = %method,
                http.route = route,
                http.response.status_code = u64::from(status.as_u16()),
                duration_ms = latency.as_secs_f64() * 1000.0,
                error.type = category,
            )
        };
    }
    if status.is_server_error() {
        emit!(Level::ERROR);
    } else if status.is_client_error() {

fn main() -> anyhow::Result<std::process::ExitCode> {
    let args = ExposedCli::parse();
    match args.command {
        Commands::Server => Ok(server_command()),
        Commands::Healthcheck => {
            tokio::runtime::Runtime::new()?.block_on(run_healthcheck())?;
            Ok(std::process::ExitCode::SUCCESS)
        }
        Commands::Migrate(args) => {
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_migrate(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
        Commands::Data(args) => {
            if let Some(response) = args.schema_response() {
                return Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?);
            }
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_cli(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
    }
}

#[allow(
    clippy::disallowed_macros,
    reason = "terminal server command failure owner"
)]
fn server_command() -> std::process::ExitCode {
    match run_server() {
        Ok(()) => std::process::ExitCode::SUCCESS,
        Err(error) => {
            if error.is::<SubscriberInitializationError>() {
                eprintln!("server tracing initialization failed");
            } else {
                // Startup errors may contain connection strings. Preserve the
                // source for callers but only report the terminal stage here.
                tracing::error!(name = "server.failed", error.type = "server.startup_or_serve");
            }
            std::process::ExitCode::FAILURE
        }
    }
}

